package com.bookstore.infrastructure.repositories;
import com.bookstore.application.orders.*; import com.bookstore.infrastructure.database.Entities.*; import java.util.*;
public final class OrderFormRepository { private static final String UNKNOWN_BOOK="Unknown book",UNKNOWN_AUTHOR="Unknown author"; private final Collection<OrderForm> forms; private final Collection<CatalogBook> books; public OrderFormRepository(Collection<OrderForm> forms,Collection<CatalogBook> books){this.forms=forms;this.books=books;} public List<RequestOrderDetailLine> getRequestOrderDetailForm(GetRequestOrderDetailFormCommand command){if(command==null||command.orderId()==null||command.orderId().isBlank())return List.of(); var form=forms.stream().filter(x->x.orderId().equals(command.orderId())).findFirst().orElse(null); if(form==null)return List.of(); var catalog=new HashMap<Integer,CatalogBook>();books.forEach(x->catalog.put(x.bookId(),x)); return form.lines().stream().sorted(Comparator.comparingInt(OrderLine::sequence)).map(x->{var b=catalog.get(x.bookId());var price=x.unitPrice();return new RequestOrderDetailLine(x.bookId(),b==null?UNKNOWN_BOOK:b.title(),b==null?UNKNOWN_AUTHOR:b.author(),x.quantity(),price,price.multiply(java.math.BigDecimal.valueOf(x.quantity())));}).toList();} }
